WITH RECURSIVE a(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM a WHERE x < 5), b(y) AS (SELECT group_concat(CURRENT_TIMESTAMP, '6 _ ') OVER (ORDER BY NOT EXISTS (SELECT CURRENT_TIMESTAMP INTERSECT SELECT * FROM (VALUES (CURRENT_TIME)) AS a GROUP BY NULL ORDER BY CURRENT_TIMESTAMP COLLATE RTRIM DESC) ASC NULLS FIRST ROWS BETWEEN CURRENT ROW AND CURRENT_DATE FOLLOWING) FROM a) SELECT * FROM b;
CREATE TABLE IF NOT EXISTS p(a INTEGER);
PRAGMA integrity_check;